@Override
public boolean equals(Object o) {
    if (this == o) {
        return true;
    }
    if (o == null || getClass() != o.getClass()) {
        return false;
    }
    EmbeddedLimits that = (EmbeddedLimits) o;
    return maxDepth == that.maxDepth && throwOnMaxDepth == that.throwOnMaxDepth && maxCount == that.maxCount && throwOnMaxCount == that.throwOnMaxCount;
}
